targets.expr:
sort_desc(
  sum by (component) (
    label_replace(
      kube_pod_info{
        pod=~"loki-(compactor|index-gateway|ruler|ingester|distributor|query-frontend|querier|pattern-ingester|query-scheduler).*",
        container!=""
      },
      "component", "$1", "pod",
      "loki-(compactor|index-gateway|ruler|ingester|distributor|query-frontend|querier|pattern-ingester|query-scheduler).*"
    )
  )
)

max(
  sum by (pod) (
    kube_pod_container_resource_limits{
      resource="cpu",
      namespace="monitoring",
      pod=~"loki-querier.*",
    }
  )
)

